        return new ArrayList<>();
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder all = new StringBuilder();
        String line;
        while ((line = br.readLine()) != null) all.append(line).append(' ');
        StringTokenizer st = new StringTokenizer(all.toString());
        int n = Integer.parseInt(st.nextToken()), m = Integer.parseInt(st.nextToken());
        String[] names = new String[n];
        for (int i = 0; i < n; i++) names[i] = st.nextToken();
        String[][] deps = new String[m][2];
        for (int i = 0; i < m; i++) {
            deps[i][0] = st.nextToken();
            deps[i][1] = st.nextToken();
        }
        String target = st.nextToken();
        List<String> res = prerequisites(names, deps, target);
        StringBuilder sb = new StringBuilder();
        sb.append(res.size()).append('\n');
        if (!res.isEmpty()) sb.append(String.join(" ", res)).append('\n');
        System.out.print(sb);
    }
}
